#!/usr/bin/env bash
# Builds the synthetic PKCS#12 fixtures tests/pkcs12_interop.rs opens. The
# point of this file is reproducibility: every shape review 04 found in real
# .p12s (Firefox/NSS BER, Java keytool, empty password, RC2-40 legacy) has to
# be generated by a real writer, not hand-assembled, or the test would prove
# nothing about interoperability.
#
# Nothing here is secret and nothing is committed: everything lands under
# testdata/certs/, which is gitignored and whose absence makes the tests skip
# (they panic instead when OPENFIRMA_REQUIRE_TESTS=1 and material is missing).
# Needs tools/gen-testcert.sh first for the synthetic PKI.
set -euo pipefail
cd "$(dirname "$0")/.."
CERTS=testdata/certs
FIX="$CERTS/p12-fixtures"
[ -f "$CERTS/signer-rsa.crt.der" ] || tools/gen-testcert.sh >/dev/null
rm -rf "$FIX"; mkdir -p "$FIX"

# The reference writer for every shape below is the same PKI, so a failure to
# open one of these files pins the bug to the container shape and not to keys.
KEY="$CERTS/signer-rsa.key"; CRT="$CERTS/signer-rsa.crt"

# --- OpenSSL / NSS empty password (A3) ---------------------------------------
# `pass:` is the empty password; OpenSSL encodes it in the MAC as BMP "00 00",
# unlike Java, which encodes zero bytes. Both spellings must open.
openssl pkcs12 -export -out "$FIX/openssl-empty.p12" -inkey "$KEY" -in "$CRT" \
  -name "empty openssl" -passout pass: -macalg sha1
# Same with the legacy PBEs, so the empty password is exercised on the PBES1
# path too (this is what setup-test-keystores.sh writes into the NSS DB).
# OpenSSL 3.6 silently DROPS -keypbe/-certpbe unless built with, or given, the
# legacy provider: the container comes out AES-wrapped while its own `-info`
# and `pkcs12` reads still happily report pbeWithSHA1And3DES, so only a second
# reader of the real shape notices (CI run 39088995737 minted an AES file from
# exactly these flags and our PBES1-strict parser refused it — correctly).
# Generate, demand the promise from a strict second reader, and re-run with
# -legacy when openssl did not honour the PBEs. The inner PKCS#7 lives inside
# the data bag's OCTET STRING (openssl's "PKCS7 Data" line above proves that
# is what it writes there), so the peel reads the outer structure directly:
# walk to `cont [0] > prim OCTET STRING` and take its hex dump. A naive "first
# long OCTET STRING" would peel the wrong element — RC2 containers carry the
# ciphertext as exactly such a run. The strict reader is openssl's own pkcs7
# parser: an AES/PBES2-wrapped authSafe never parses under PBE-SHA1-3DES.
authsafe_is_pbdes() {
  # $1 = p12 file. True when the data bag's inner ContentInfo is an
  # EncryptedData over PBE-SHA1-3DES, read from bytes, not from openssl's
  # opinion about its own output. No `-strhex`: this openssl build does not
  # have it. The peel walks the printed tree instead — outer SEQUENCE,
  # INTEGER version, the data bag's SEQUENCE, and the OCTET STRING under
  # `cont [0]` carry their full hex in the `[HEX DUMP]:` text that even this
  # build prints. A naive "first long OCTET STRING" would peel the wrong
  # element; RC2 containers carry ciphertext as exactly such a run. The
  # strict reader is openssl's own pkcs7 parser: an AES/PBES2-wrapped
  # authSafe never parses under PBE-SHA1-3DES.
  local der="$1" hex inner
  hex="$(openssl asn1parse -inform DER -in "$der" 2>/dev/null |
    awk '/cons: cont \[ 0 \]/ { want = 1; next }
         want && /prim: OCTET STRING/ { sub(/^.*HEX DUMP]:/, ""); print; exit }')" || hex=""
  [ -n "$hex" ] || return 1
  inner="$der.inner.$$"
  printf '%s' "$hex" | python3 -c 'import sys,binascii; sys.stdout.buffer.write(binascii.unhexlify(sys.stdin.read().strip()))' > "$inner" 2>/dev/null || { rm -f "$inner"; return 1; }
  # The inner ContentInfo is an AuthSafe (a bare SEQUENCE of SafeBags), not a
  # PKCS7; the strict reader runs on the pieces. It must contain exactly one
  # EncryptedData — the wrapped authSafe, whose encryption algorithm must be
  # pbeWithSHA1And3DES — and the key bag's shrouding must be PBES1 too. An
  # AES/PBES2-wrapped container fails this at once: that is exactly the drift
  # CI run 39088995737 minted.
  local info ok=0 n_enc
  info="$(openssl asn1parse -inform DER -in "$inner" 2>/dev/null)"
  rm -f "$inner"
  n_enc="$(printf '%s' "$info" | grep -c 'pkcs7-encryptedData')" || n_enc=0
  [ "$n_enc" -eq 1 ] || ok=1
  printf '%s' "$info" | grep -qiE 'pbeWithSHA1And3|PBE-SHA1-3DES' || ok=1
  return "$ok"
}
gen_empty_legacy() {
  openssl pkcs12 -export -out "$FIX/openssl-empty-legacy.p12" -inkey "$KEY" -in "$CRT" \
    -name "empty openssl legacy" -passout pass: \
    -keypbe PBE-SHA1-3DES -certpbe PBE-SHA1-3DES -macalg sha1 "$@" 2>/dev/null ||
    { echo "error: openssl pkcs12 -export failed for openssl-empty-legacy.p12" >&2; return 1; }
}
gen_empty_legacy
if ! authsafe_is_pbdes "$FIX/openssl-empty-legacy.p12"; then
  gen_empty_legacy -legacy || exit 1
  if ! authsafe_is_pbdes "$FIX/openssl-empty-legacy.p12"; then
    echo "error: openssl cannot write a PBE-SHA1-3DES container even with -legacy on this machine; the PBES1 fixtures cannot be generated here" >&2
    exit 1
  fi
fi

# --- Java 11+ keytool (A1) ---------------------------------------------------
# The modern default PKCS12 store: PBES2 with AES-256-CBC, HMAC-SHA256 MAC and
# — the part openfirma refused — a keyLength INTEGER in every PBKDF2 parameters.
if command -v keytool >/dev/null 2>&1; then
  JKS="$FIX/keytool.jks"
  # keytool imports a PKCS#12 only through a JKS detour because the same-key
  # export would otherwise read back the file openssl wrote with its own
  # parameters; the round trip guarantees every field is keytool's.
  keytool -importkeystore -deststoretype pkcs12 -destkeystore "$JKS" \
    -srckeystore "$CERTS/signer-rsa.p12" -srcstoretype PKCS12 -srcstorepass openfirma \
    -deststorepass openfirma -noprompt >/dev/null 2>&1
  keytool -importkeystore -srckeystore "$JKS" -srcstoretype JKS -srcstorepass openfirma \
    -destkeystore "$FIX/java-default.p12" -deststoretype PKCS12 -deststorepass openfirma \
    -noprompt >/dev/null 2>&1 \
    || echo "warning: keytool could not re-export; java-default.p12 absent, its test skips" >&2
  # The Java "legacy" shape (-Dkeystore.pkcs12.legacy): 3DES key bag, RC2-40
  # cert bag — the file old Java wrote by default and Keystore Explorer still
  # can. Skipped when a JDK too new to carry the property refuses it.
  keytool -J-Dkeystore.pkcs12.legacy -importkeystore -srckeystore "$JKS" \
    -srcstoretype JKS -srcstorepass openfirma \
    -destkeystore "$FIX/java-legacy.p12" -deststoretype PKCS12 -deststorepass openfirma \
    -noprompt >/dev/null 2>&1 || rm -f "$FIX/java-legacy.p12"
  # The keytool shape with an empty password (A3 x A1), assembled from the
  # real java-default.p12 by re-deriving its MAC: same PBES2 encryption of the
  # safe bags, only the MAC moves to the empty-password BMP spelling — which
  # is exactly what a Java tool that allowed empty passwords would write.
  if [ -f "$FIX/java-default.p12" ]; then
    python3 tools/p12-empty-mac.py "$FIX/java-default.p12" "$FIX/java-empty.p12" \
      || echo "warning: could not re-MAC java-empty.p12; its test skips" >&2
  fi
  # Java legacy with an empty password (what `empty-legacy.p12` of review 04
  # is): same rewrite over the legacy file.
  if [ -f "$FIX/java-legacy.p12" ]; then
    python3 tools/p12-empty-mac.py "$FIX/java-legacy.p12" "$FIX/java-empty-legacy.p12" \
      || echo "warning: could not re-MAC java-empty-legacy.p12; its test skips" >&2
  fi
else
  echo "warning: no keytool on PATH; java-default.p12 / java-legacy.p12 will be absent and those tests skip" >&2
fi

# --- RC2-40 (A2) -------------------------------------------------------------
# The legacy cert-bag cipher, generated with the writers that actually used
# it. OpenSSL 3 hides RC2 behind the legacy provider; probing is done by
# writing a tiny ciphertext, and pkcs12 -export needs the providers passed
# explicitly (`-provider legacy -provider default`). Without a legacy provider
# this is skipped and its test says so.
RC2_OK=0
if printf 'probe' | openssl enc -provider legacy -provider default -rc2-40-cbc \
     -pass pass:x -P >/dev/null 2>&1; then
  RC2_OK=1
fi
if [ "$RC2_OK" = 1 ]; then
  openssl pkcs12 -export -provider legacy -provider default \
    -out "$FIX/rc2-certs.p12" -inkey "$KEY" -in "$CRT" \
    -name "rc2 certs" -passout pass:openfirma \
    -certpbe RC2-40-CBC -keypbe PBE-SHA1-3DES -macalg sha1 2>/dev/null \
    || echo "warning: openssl could not write rc2-certs.p12; its test skips" >&2
  # The macOS Keychain's exact export shape (review 04 could not confirm it on
  # a Mac): RC2-40 on BOTH bags with a SHA-1 MAC.
  openssl pkcs12 -export -provider legacy -provider default \
    -out "$FIX/rc2-both.p12" -inkey "$KEY" -in "$CRT" \
    -name "rc2 both" -passout pass:openfirma \
    -certpbe RC2-40-CBC -keypbe RC2-40-CBC -macalg sha1 2>/dev/null || true
else
  echo "warning: no legacy provider with RC2 in this openssl; the rc2 fixtures skip" >&2
fi

# --- NSS / pk12util (C2) ------------------------------------------------------
# The exact file Firefox's "Hacer copia..." produces (pk12util is the same
# code), which is BER with indefinite lengths and constructed OCTET STRINGs.
if command -v pk12util >/dev/null 2>&1; then
  SRC="$FIX/nss-src"
  rm -rf "$SRC"; mkdir -p "$SRC"
  # A passwordless key-side (certutil --empty-password) but the p12 import
  # still carries its own -W password: exactly how a Firefox profile with no
  # master password holds an imported FNMT certificate.
  certutil -N -d "sql:$SRC" --empty-password >/dev/null 2>&1 || true
  pk12util -i "$CERTS/signer-rsa.p12" -d "sql:$SRC" -W openfirma >/dev/null
  # The nickname is what the DB stored from the friendlyName of the import;
  # ask the DB for it. certutil's listing pads every name to a column, so cut
  # the trust attributes off at their opening parenthesis (they read like
  # "(u,u,u)") and trim; DNs full of commas survive that untouched.
  NICK=$(certutil -L -d "sql:$SRC" 2>/dev/null | grep 'u,u,u' \
    | sed 's/  *[^ ]*$//' | head -1)
  [ -n "$NICK" ] || NICK='PEREZ GARCIA, ANA'
  # The export password: -W takes it on the command line (a visible argument;
  # this is a throwaway synthetic file), -k reads it from a file and prompts
  # for confirmation when the DB has no slot password, which no test runner
  # without a terminal survives.
  if pk12util -o "$FIX/nss-export.p12" -d "sql:$SRC" -W openfirma -n "$NICK" >/dev/null 2>&1; then
    # The MAC of the export we just made is over a password the reader will
    # try both spellings for; to cover the *empty* Firefox backup too, export
    # again with an empty p12file password.
    pk12util -o "$FIX/nss-export-empty.p12" -d "sql:$SRC" -W '' -n "$NICK" >/dev/null \
      || echo "warning: pk12util empty-password export failed; its test skips" >&2
  else
    echo "warning: pk12util export failed; nss-export*.p12 absent, those tests skip" >&2
  fi
else
  echo "warning: no pk12util (libnss3-tools); nss-export*.p12 absent, those tests skip" >&2
fi

ls "$FIX"/*.p12 2>/dev/null || true
echo "fixtures in $FIX"

# --- verify every fixture against its declared producer password --------------
# The point of these files is interoperability: a container whose MAC does not
# verify under the password its own writer wrote it with proves nothing about
# anyone, and tests reading it then fail somewhere far away (a "wrong password"
# deep in an interop test is weeks from the broken writer). So each fixture that
# carries a password gets opened right here by the producer that made it:
# keytool -list for its own shapes, openssl pkcs12 for OpenSSL's. RC2 containers
# and BER files need the legacy provider or a reader that has one, so they are
# checked with whichever tool can see them, and nss-* / java-empty-legacy (whose
# java shape is produced here rather than by keytool itself) verify through our
# own reader when cargo is available. A fixture that fails here stops the build:
# the producer mismatch IS the bug this whole script exists to catch.
echo "== verifying fixtures against their declared passwords =="
fail=0
check_keytool() {
  # $1: file, $2: password. The java reader is the reference for java shapes;
  # the appended empty-MAC spellings must not confuse it (it opens with the
  # original store password). A refusal here means keytool's own writer and
  # reader disagree about this container, which is exactly what review 04 said.
  if ! keytool -list -keystore "$FIX/$1" -storepass "$2" >/dev/null 2>&1; then
    echo "error: keytool cannot open its own $1 with the password it wrote it with" >&2
    fail=1
  fi
}
check_openssl() {
  # openssl 3 needs the legacy provider to even read an RC2 container's bags,
  # but -noout only parses the MAC layer; still, pass both providers so one
  # rule covers every shape.
  if ! openssl pkcs12 -in "$FIX/$1" -noout -passin "pass:$2" \
       -provider legacy -provider default >/dev/null 2>&1; then
    echo "error: openssl cannot open $1 with the declared password" >&2
    fail=1
  fi
}
[ -f "$FIX/java-default.p12" ] && check_keytool java-default.p12 openfirma
[ -f "$FIX/java-legacy.p12" ] && check_keytool java-legacy.p12 openfirma
check_openssl openssl-empty.p12 ""
check_openssl openssl-empty-legacy.p12 ""
[ -f "$FIX/rc2-certs.p12" ] && check_openssl rc2-certs.p12 openfirma
[ -f "$FIX/rc2-both.p12" ] && check_openssl rc2-both.p12 openfirma
if [ "$fail" -ne 0 ]; then
  echo "a fixture does not verify for the password its producer wrote: that is a generator bug, not a test failure" >&2
  exit 1
fi
